  .pref-tile-icon { font-size: 36px; margin-bottom: 4px; }
  .pref-tile-label { font-size: 11px; }

  /* ====== FINDER ====== */
  .finder-app { display: flex; height: 100%; font-size: 12px; background: white; }
  .finder-sidebar {
    width: 130px; background: #ececec; border-right: 1px solid #888;
