<script>
/* ============================================================
   CORE STATE & UTILITIES
   ============================================================ */
const $ = (sel, root=document) => root.querySelector(sel);
const $$ = (sel, root=document) => [...root.querySelectorAll(sel)];

let windowZIndex = 100;
let windowIdCounter = 0;
let cascadeOffset = 0;
const openWindows = new Map(); // id -> window element
let activeWindowId = null;
let draggedWindow = null;
let dragOffset = { x: 0, y: 0 };
let resizingWindow = null;
let resizeStart = { x: 0, y: 0, w: 0, h: 0 };

function uid() { return 'w' + (++windowIdCounter); }

/* ============================================================
   BOOT SEQUENCE
   ============================================================ */
function runBoot() {
  const bar = $('#boot-bar');
  let p = 0;
  const messages = [
    'Starting Mac OS 9...', 'Initializing memory...', 'Loading extensions...',
    'Mounting disks...', 'Starting Finder...', 'Welcome!'
  ];
  const bootText = $('#boot .boot-text');
  const interval = setInterval(() => {
    p += Math.random() * 12 + 4;
    if (p > 100) p = 100;
    bar.style.width = p + '%';
    const msgIdx = Math.min(Math.floor(p / 20), messages.length - 1);
    bootText.textContent = messages[msgIdx];
    if (p >= 100) {
      clearInterval(interval);
      setTimeout(() => {
        $('#boot').style.transition = 'opacity 0.5s';
        $('#boot').style.opacity = '0';
        setTimeout(() => {
          $('#boot').style.display = 'none';
          $('#desktop').style.display = 'block';
          // Auto-open Finder on boot
          openApp('finder');
        }, 500);
      }, 400);
    }
  }, 250);
}

/* ============================================================
   CLOCK
   ============================================================ */
function updateClock() {
  const d = new Date();
  let h = d.getHours();
  const m = d.getMinutes().toString().padStart(2, '0');
  const ampm = h >= 12 ? 'PM' : 'AM';
  h = h % 12 || 12;
  $('#mb-clock').textContent = `${h}:${m} ${ampm}`;
}
setInterval(updateClock, 1000);
updateClock();

/* ============================================================
   MENU BAR / DROPDOWNS
   ============================================================ */
const menus = {
  apple: [
    { label: 'About This Mac', action: () => openApp('about') },
    { divider: true },
    { label: 'System Preferences…', shortcut: '⌘Y', action: () => openApp('preferences') },
    { label: 'Control Panels', hasSub: true, sub: [
      { label: 'Sound' }, { label: 'Display' }, { label: 'Mouse' },
      { label: 'Keyboard' }, { label: 'Date & Time' }
    ]},
    { label: 'Applications', hasSub: true, sub: [
      { label: 'Calculator', action: () => openApp('calculator') },
      { label: 'TextEdit', action: () => openApp('textedit') },
      { label: 'Stickies', action: () => openApp('stickies') },
      { label: 'MacPaint', action: () => openApp('drawing') },
      { label: 'Minesweeper', action: () => openApp('mines') },
    ]},
    { divider: true },
    { label: 'Empty Trash', action: () => alert('Trash is empty!') },
    { divider: true },
    { label: 'Sleep', shortcut: '⌘⏏' },
    { label: 'Restart…' },
    { label: 'Shut Down…' },
  ],
  file: [
    { label: 'New', shortcut: '⌘N', hasSub: true, sub: [
      { label: 'Text Document', action: () => openApp('textedit') },
      { label: 'Sticky Note', action: () => openApp('stickies') },
      { label: 'Drawing', action: () => openApp('drawing') },
    ]},
    { label: 'Open…', shortcut: '⌘O' },
    { label: 'Open Recent', hasSub: true, sub: [
      { label: 'README.txt' }, { label: 'Sketch.paint' }, { label: 'Notes' }
    ]},
    { label: 'Close', shortcut: '⌘W', action: () => {
      if (activeWindowId) closeWindow(activeWindowId);
    }},
    { label: 'Save', shortcut: '⌘S' },
    { divider: true },
    { label: 'Get Info', shortcut: '⌘I' },
    { label: 'Duplicate', shortcut: '⌘D' },
  ],
  edit: [
    { label: 'Undo', shortcut: '⌘Z' },
    { label: 'Redo', shortcut: '⇧⌘Z' },
    { divider: true },
    { label: 'Cut', shortcut: '⌘X' },
    { label: 'Copy', shortcut: '⌘C' },
    { label: 'Paste', shortcut: '⌘V' },
    { label: 'Clear' },
    { label: 'Select All', shortcut: '⌘A' },
    { divider: true },
    { label: 'Find', shortcut: '⌘F' },
  ],
  view: [
    { label: 'as Icons', shortcut: '⌘1' },
    { label: 'as List', shortcut: '⌘2' },
    { label: 'as Buttons', shortcut: '⌘3' },
    { divider: true },
    { label: 'Clean Up' },
    { label: 'Sort By', hasSub: true, sub: [
      { label: 'Name' }, { label: 'Date' }, { label: 'Size' }, { label: 'Kind' }
    ]},
  ],
  special: [
    { label: 'Desktop', shortcut: 'F11' },
    { label: 'Eject Disk' },
    { divider: true },
    { label: 'Empty Cache' },
    { label: 'Restart Finder' },
  ],
  window: [
    { label: 'Cascade' },
    { label: 'Tile' },
    { label: 'Arrange Icons' },
    { divider: true },
  ],
  help: [
    { label: 'Mac OS Help' },
    { label: 'How Do I…' },
    { label: 'Show Balloons', shortcut: '⌘?' },
    { divider: true },
    { label: 'About Mac OS Help' },
  ]
};

let currentDropdown = null;

function closeAllDropdowns() {
  $$('.dropdown').forEach(d => d.remove());
  $$('.menu-item.open').forEach(m => m.classList.remove('open'));
  currentDropdown = null;
}

function showMenu(name, anchor) {
  closeAllDropdowns();
  if (!menus[name]) return;
  anchor.classList.add('open');
  const dd = document.createElement('div');
  dd.className = 'dropdown';
  const rect = anchor.getBoundingClientRect();
  dd.style.left = rect.left + 'px';
  dd.style.top = rect.bottom + 'px';

  menus[name].forEach(item => {
    if (item.divider) {
      const d = document.createElement('div');
      d.className = 'dropdown-item divider';
      dd.appendChild(d);
      return;
    }
    const el = document.createElement('div');
    el.className = 'dropdown-item' + (item.hasSub ? ' has-sub' : '');
    el.innerHTML = `<span>${item.label}</span>${item.shortcut ? `<span class="shortcut">${item.shortcut}</span>` : ''}`;
    el.addEventListener('click', (e) => {
      e.stopPropagation();
      if (item.hasSub) return;
      if (item.action) item.action();
      closeAllDropdowns();
    });
    if (item.hasSub) {
      let subMenu;
      el.addEventListener('mouseenter', () => {
        $$('.submenu').forEach(s => s.remove());
        subMenu = document.createElement('div');
        subMenu.className = 'dropdown submenu';
        const r = el.getBoundingClientRect();
        subMenu.style.left = r.right + 'px';
        subMenu.style.top = r.top + 'px';
        item.sub.forEach(s => {
          const se = document.createElement('div');
          se.className = 'dropdown-item';
          se.textContent = s.label;
          se.addEventListener('click', (ev) => {
            ev.stopPropagation();
            if (s.action) s.action();
            closeAllDropdowns();
          });
          subMenu.appendChild(se);
        });
        document.body.appendChild(subMenu);
      });
    }
    dd.appendChild(el);
  });
  document.body.appendChild(dd);
  currentDropdown = dd;
}

$$('#menu-bar .menu-item[data-menu]').forEach(mi => {
  mi.addEventListener('mousedown', (e) => {
    e.stopPropagation();
    showMenu(mi.dataset.menu, mi);
  });
});

document.addEventListener('mousedown', (e) => {
  if (currentDropdown && !currentDropdown.contains(e.target) && !e.target.closest('.menu-item')) {
    closeAllDropdowns();
  }
  if (!e.target.closest('.desktop-icon')) {
    $$('.desktop-icon.selected').forEach(i => i.classList.remove('selected'));
  }
});

/* ============================================================
   DESKTOP ICONS
   ============================================================ */
$$('.desktop-icon').forEach(icon => {
  icon.addEventListener('mousedown', (e) => {
    e.stopPropagation();
    $$('.desktop-icon.selected').forEach(i => i.classList.remove('selected'));
    icon.classList.add('selected');
    if (e.detail === 2) { // double click
      const name = icon.dataset.icon;
      if (name === 'macintosh-hd') openApp('finder');
      else if (name === 'trash') alert('Trash is empty.');
    }
  });
});

/* ============================================================
   DOCK
   ============================================================ */
$$('.dock-item').forEach(item => {
  item.addEventListener('click', (e) => {
    e.stopPropagation();
    openApp(item.dataset.app);
  });
});

/* ============================================================
   WINDOW MANAGEMENT
   ============================================================ */
function focusWindow(id) {
  activeWindowId = id;
  openWindows.forEach((w, wid) => {
    if (wid === id) {
      w.style.zIndex = ++windowZIndex;
      w.classList.remove('inactive');
    } else {
      w.classList.add('inactive');
    }
  });
}

function makeDraggable(winEl, titleBar) {
  titleBar.addEventListener('mousedown', (e) => {
    if (e.target.closest('.window-control')) return;
    const id = winEl.dataset.id;
    focusWindow(id);
    if (winEl.classList.contains('maximized')) return;
    draggedWindow = winEl;
    const rect = winEl.getBoundingClientRect();
    dragOffset.x = e.clientX - rect.left;
    dragOffset.y = e.clientY - rect.top;
    winEl.classList.add('no-select');
    e.preventDefault();
  });
}

function makeResizable(winEl) {
  const handle = winEl.querySelector('.window-resize');
  handle.addEventListener('mousedown', (e) => {
    e.stopPropagation();
    const id = winEl.dataset.id;
    focusWindow(id);
    if (winEl.classList.contains('maximized')) return;
    resizingWindow = winEl;
    resizeStart.x = e.clientX;
    resizeStart.y = e.clientY;
    resizeStart.w = winEl.offsetWidth;
    resizeStart.h = winEl.offsetHeight;
    e.preventDefault();
  });
}

document.addEventListener('mousemove', (e) => {
  if (draggedWindow) {
    const x = e.clientX - dragOffset.x;
    const y = e.clientY - dragOffset.y;
    draggedWindow.style.left = Math.max(-100, Math.min(window.innerWidth - 50, x)) + 'px';
    draggedWindow.style.top = Math.max(22, Math.min(window.innerHeight - 50, y)) + 'px';
  }
  if (resizingWindow) {
    const dx = e.clientX - resizeStart.x;
    const dy = e.clientY - resizeStart.y;
    resizingWindow.style.width = Math.max(180, resizeStart.w + dx) + 'px';
    resizingWindow.style.height = Math.max(100, resizeStart.h + dy) + 'px';
    // Trigger resize event for canvases
    resizingWindow.dispatchEvent(new Event('resize'));
  }
});

document.addEventListener('mouseup', () => {
  draggedWindow = null;
  resizingWindow = null;
});

function closeWindow(id) {
  const w = openWindows.get(id);
  if (!w) return;
  // Animate to dock
  w.classList.add('minimizing');
  w.style.transform = 'scale(0.1)';
  w.style.opacity = '0';
  setTimeout(() => {
    w.remove();
    openWindows.delete(id);
  }, 250);
}

function minimizeWindow(id) {
  const w = openWindows.get(id);
  if (!w) return;
  // Get dock item for this app
  const appType = w.dataset.appType;
  const dockItem = $(`.dock-item[data-app="${appType}"]`);
  if (dockItem) {
    const rect = dockItem.getBoundingClientRect();
    const wrect = w.getBoundingClientRect();
    const tx = (rect.left + rect.width/2) - (wrect.left + wrect.width/2);
    const ty = (rect.top + rect.height/2) - (wrect.top + wrect.height/2);
    w.style.transition = 'transform 0.4s, opacity 0.4s';
    w.style.transformOrigin = 'bottom left';
    w.style.transform = `translate(${tx}px, ${ty}px) scale(0.1)`;
    w.style.opacity = '0';
    setTimeout(() => {
      w.style.display = 'none';
      w.style.transition = '';
      w.style.transform = '';
      w.style.opacity = '';
    }, 400);
  }
}

function maximizeWindow(id) {
  const w = openWindows.get(id);
  if (!w) return;
  if (w.classList.contains('maximized')) {
    w.classList.remove('maximized');
    w.style.left = w.dataset.prevLeft;
    w.style.top = w.dataset.prevTop;
    w.style.width = w.dataset.prevWidth;
    w.style.height = w.dataset.prevHeight;
  } else {
    w.dataset.prevLeft = w.style.left;
    w.dataset.prevTop = w.style.top;
    w.dataset.prevWidth = w.style.width;
    w.dataset.prevHeight = w.style.height;
    w.classList.add('maximized');
    w.style.left = '0';
    w.style.top = '22px';
    w.style.width = '100vw';
    w.style.height = 'calc(100vh - 22px - 78px)';
  }
  w.dispatchEvent(new Event('resize'));
}

