  about: { title: 'About This Mac', w: 320, h: 240, build: buildAbout },
  browser: { title: 'Internet Explorer', w: 540, h: 440, build: buildBrowser },
};

function openApp(appType) {
  // Check if already open - focus instead of opening new
  for (const [id, w] of openWindows) {
    if (w.dataset.appType === appType && w.style.display !== 'none') {
      w.style.display = '';
      w.style.transform = 'scale(0.7)';
      w.style.opacity = '0';
      w.style.transition = 'transform 0.2s, opacity 0.2s';
      requestAnimationFrame(() => {
        w.style.transform = 'scale(1)';
        w.style.opacity = '1';
        setTimeout(() => {
          w.style.transition = '';
          w.style.transform = '';
          w.style.opacity = '';
        }, 200);
      });
      focusWindow(id);
      return;
    }
  }
  // Check minimized
  for (const [id, w] of openWindows) {
    if (w.dataset.appType === appType && w.style.display === 'none') {
      w.style.display = '';
      w.style.transition = 'transform 0.2s, opacity 0.2s';
      w.style.transform = 'scale(0.7)';
      w.style.opacity = '0';
      requestAnimationFrame(() => {
        w.style.transform = 'scale(1)';
        w.style.opacity = '1';
        setTimeout(() => {
          w.style.transition = '';
          w.style.transform = '';
          w.style.opacity = '';
        }, 200);
      });
      focusWindow(id);
      return;
    }
  }

  const cfg = appConfigs[appType];
  if (!cfg) return;
  const id = uid();
  const w = document.createElement('div');
  w.className = 'window';
  w.dataset.id = id;
  w.dataset.appType = appType;
  cascadeOffset = (cascadeOffset + 24) % 200;
  const x = 80 + cascadeOffset;
  const y = 50 + cascadeOffset;
  w.style.left = x + 'px';
  w.style.top = y + 'px';
  w.style.width = cfg.w + 'px';
  w.style.height = cfg.h + 'px';
  w.innerHTML = `
    <div class="window-titlebar">
      <div class="window-controls">
        <div class="window-control close" title="Close">×</div>
        <div class="window-control minimize" title="Minimize">−</div>
        <div class="window-control maximize" title="Zoom">+</div>
      </div>
      <div class="window-title">${cfg.title}</div>
    </div>
    <div class="window-content"></div>
    <div class="window-resize"></div>
  `;
  $('#windows-container').appendChild(w);
  openWindows.set(id, w);
  focusWindow(id);

  cfg.build(w.querySelector('.window-content'), w);

  // Animate open
  w.style.transform = 'scale(0.8)';
  w.style.opacity = '0';
  w.style.transition = 'transform 0.2s, opacity 0.2s';
  requestAnimationFrame(() => {
    w.style.transform = 'scale(1)';
    w.style.opacity = '1';
    setTimeout(() => {
      w.style.transition = '';
      w.style.transform = '';
      w.style.opacity = '';
    }, 200);
  });

  // Mark dock item running
  const dockItem = $(`.dock-item[data-app="${appType}"]`);
  if (dockItem) dockItem.classList.add('running');

  // Window controls
  w.querySelector('.window-control.close').addEventListener('click', () => {
    closeWindow(id);
    // Check if any other windows of same type
    let stillOpen = false;
    openWindows.forEach(ow => { if (ow.dataset.appType === appType) stillOpen = true; });
    if (!stillOpen && dockItem) dockItem.classList.remove('running');
  });
  w.querySelector('.window-control.minimize').addEventListener('click', () => minimizeWindow(id));
  w.querySelector('.window-control.maximize').addEventListener('click', () => maximizeWindow(id));
  w.addEventListener('mousedown', () => focusWindow(id));
  makeDraggable(w, w.querySelector('.window-titlebar'));
  makeResizable(w);
}

