function buildCalculator(content, win) {
  content.innerHTML = `
    <div class="calc-app">
      <div class="calc-display" id="calc-disp">0</div>
      <div class="calc-buttons">
        <div class="calc-btn clear" data-k="C">C</div>
        <div class="calc-btn" data-k="±">±</div>
        <div class="calc-btn" data-k="%">%</div>
        <div class="calc-btn op" data-k="÷">÷</div>
        <div class="calc-btn" data-k="7">7</div>
        <div class="calc-btn" data-k="8">8</div>
        <div class="calc-btn" data-k="9">9</div>
        <div class="calc-btn op" data-k="×">×</div>
        <div class="calc-btn" data-k="4">4</div>
        <div class="calc-btn" data-k="5">5</div>
        <div class="calc-btn" data-k="6">6</div>
        <div class="calc-btn op" data-k="−">−</div>
        <div class="calc-btn" data-k="1">1</div>
        <div class="calc-btn" data-k="2">2</div>
        <div class="calc-btn" data-k="3">3</div>
        <div class="calc-btn op" data-k="+">+</div>
        <div class="calc-btn wide" data-k="0">0</div>
        <div class="calc-btn" data-k=".">.</div>
        <div class="calc-btn eq" data-k="=">=</div>
      </div>
    </div>
  `;
  const disp = content.querySelector('#calc-disp');
  let cur = '0', prev = null, op = null, justComputed = false;
  function update(v) { disp.textContent = v.length > 12 ? v : v; if (v.length > 12) disp.style.fontSize = '14px'; else disp.style.fontSize = '24px'; }
  function compute() {
    if (prev === null || op === null) return parseFloat(cur);
    const a = parseFloat(prev), b = parseFloat(cur);
    if (op === '+') return a + b;
    if (op === '−') return a - b;
    if (op === '×') return a * b;
    if (op === '÷') return b === 0 ? 'Error' : a / b;
    return b;
  }
  content.querySelectorAll('.calc-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const k = btn.dataset.k;
      if (k === 'C') { cur = '0'; prev = null; op = null; update('0'); return; }
      if (k === '±') { cur = (parseFloat(cur) * -1).toString(); update(cur); return; }
      if (k === '%') { cur = (parseFloat(cur) / 100).toString(); update(cur); return; }
      if ('0123456789'.includes(k)) {
        if (cur === '0' || justComputed) { cur = k; justComputed = false; }
        else cur += k;
        update(cur); return;
      }
      if (k === '.') {
        if (!cur.includes('.')) cur += '.';
        update(cur); return;
      }
      if (['+','−','×','÷'].includes(k)) {
        if (prev !== null && op && !justComputed) {
          const r = compute();
          cur = String(r);
          update(cur);
        }
        prev = cur;
        op = k;
        justComputed = true;
        return;
      }
      if (k === '=') {
        const r = compute();
        cur = String(r);
        prev = null; op = null;
        justComputed = true;
        update(cur);
      }
    });
  });
}

