function buildDrawing(content, win) {
  const winId = win.dataset.id;
  const colors = ['#000000', '#ffffff', '#ff0000', '#00aa00', '#0000ff', '#ffff00', '#ff00ff', '#00ffff', '#ff8800', '#8800ff'];
  let currentColor = '#000000';
  let brushSize = 4;
  let drawing = false;
  let lastX = 0, lastY = 0;
  let tool = 'brush';

  content.innerHTML = `
    <div class="drawing-app">
      <div class="drawing-toolbar">
        <span style="font-size:11px;">Color:</span>
        <span id="swatches-${winId}"></span>
        <label>Size: <input type="range" id="size-${winId}" min="1" max="30" value="4" style="vertical-align:middle;width:100px;"></label>
        <span id="sizeval-${winId}" style="font-size:11px;">4</span>
        <button class="btn" id="tool-brush-${winId}">✏️ Brush</button>
        <button class="btn" id="tool-eraser-${winId}">🧽 Eraser</button>
        <button class="btn" id="clear-${winId}">🗑️ Clear</button>
        <button class="btn" id="fill-${winId}">🪣 Fill</button>
      </div>
      <canvas class="drawing-canvas" id="canvas-${winId}"></canvas>
    </div>
  `;
  const canvas = content.querySelector(`#canvas-${winId}`);
  const ctx = canvas.getContext('2d');
  function resizeCanvas() {
    const old = canvas.toDataURL();
    const rect = canvas.parentElement.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height - 40;
    ctx.fillStyle = 'white';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    if (old && old.length > 100) {
      const img = new Image();
      img.onload = () => ctx.drawImage(img, 0, 0);
      img.src = old;
    }
  }
  setTimeout(resizeCanvas, 50);
  win.addEventListener('resize', resizeCanvas);

  const swatches = content.querySelector(`#swatches-${winId}`);
  colors.forEach((c, i) => {
    const s = document.createElement('span');
    s.className = 'color-swatch' + (i === 0 ? ' active' : '');
    s.style.background = c;
    if (c === '#ffffff') s.style.background = `linear-gradient(45deg, #fff 50%, #ccc 50%)`;
    s.addEventListener('click', () => {
      currentColor = c;
      $$('.color-swatch', swatches).forEach(x => x.classList.remove('active'));
      s.classList.add('active');
    });
    swatches.appendChild(s);
  });

  const sizeInput = content.querySelector(`#size-${winId}`);
  const sizeVal = content.querySelector(`#sizeval-${winId}`);
  sizeInput.addEventListener('input', () => {
    brushSize = parseInt(sizeInput.value);
    sizeVal.textContent = brushSize;
  });

  function setTool(t) { tool = t; }
  content.querySelector(`#tool-brush-${winId}`).addEventListener('click', () => setTool('brush'));
  content.querySelector(`#tool-eraser-${winId}`).addEventListener('click', () => setTool('eraser'));
  content.querySelector(`#clear-${winId}`).addEventListener('click', () => {
    ctx.fillStyle = 'white';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  });
  content.querySelector(`#fill-${winId}`).addEventListener('click', () => {
    ctx.fillStyle = currentColor;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  });

  function getPos(e) {
    const rect = canvas.getBoundingClientRect();
    return { x: e.clientX - rect.left, y: e.clientY - rect.top };
  }
  canvas.addEventListener('mousedown', (e) => {
    const p = getPos(e);
    if (tool === 'fill') { ctx.fillStyle = currentColor; ctx.fillRect(0, 0, canvas.width, canvas.height); return; }
    drawing = true;
    lastX = p.x; lastY = p.y;
    ctx.beginPath();
    ctx.fillStyle = tool === 'eraser' ? 'white' : currentColor;
    ctx.arc(p.x, p.y, brushSize/2, 0, Math.PI * 2);
    ctx.fill();
  });
  canvas.addEventListener('mousemove', (e) => {
    if (!drawing) return;
    const p = getPos(e);
    ctx.strokeStyle = tool === 'eraser' ? 'white' : currentColor;
    ctx.lineWidth = brushSize;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(lastX, lastY);
    ctx.lineTo(p.x, p.y);
    ctx.stroke();
    lastX = p.x; lastY = p.y;
  });
  canvas.addEventListener('mouseup', () => drawing = false);
  canvas

