            text-overflow: ellipsis;
        }

        /* --- Windows --- */
        #windows-container {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            pointer-events: none; /* Let clicks pass through to desktop if not over window */
            z-index: 50;
        }

        .window {
            position: absolute;
            width: 500px;
            height: 350px;
            background: var(--window-bg);
            border: 1px solid var(--window-border);
            border-radius: 8px;
            box-shadow: var(--shadow);
            pointer-events: all;
            display: flex;
            flex-direction: column;
            overflow: hidden;
            min-width: 300px;
            min-height: 200px;
            /* Animation for appearing */
            animation: slideIn 0.2s ease-out;
        }

        @keyframes slideIn {
            from { transform: translateY(20px); opacity: 0; }
            to { transform: translateY(0); opacity: 1; }
        }

        .window.minimized {
            height: 0;
            opacity: 0;
            pointer-events: none;
        }

        /* Title Bar */
        .title-bar {
            height: 28px;
            background: var(--title-bar-bg);
            display: flex;
            align-items: center;
            padding: 0 10px;
            justify-content: space-between;
            border-bottom: 1px solid var(--window-border);
            cursor: move; /* Indicates draggable */
        }

        .title-bar .left-controls {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .window-control {
            width: 12px;
            height: 12px;
            border-radius: 50%;
            display: inline-block;
        }

        .close-btn { background: #ff5f56; }
        .minimize-btn { background: #ffbd2e; }
        .zoom-btn { background: #27c93f; }

        .title-text {
            position: absolute;
            left: 50%;
            transform: translateX(-50%);
            font-size: 13px;
            font-weight: 500;
            color: var(--title-bar-text);
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            pointer-events: none;
            width: 80%;
            text-align: center;
        }

        /* Content Area */
        .window-content {
            flex: 1;
            overflow: hidden;
            position: relative;
            background: #fff;
        }

        /* Specific App Styles */

        /* Calculator */
        .calc-display {
            width: 100%;
            height: 60px;
            background: #2d2d2d;
            color: #fff;
            font-family: var(--monospace-font);
            font-size: 24px;
            display: flex;
            align-items: center;
            justify-content: flex-end;
            padding: 0 15px;
            border-bottom: 1px solid #444;
        }

        .calc-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 1px;
            flex: 1;
            background: #ccc;
            padding: 1px;
        }

        .calc-btn {
            border: none;
            background: #f0f0f0;
            font-size: 18px;
            font-family: var(--text-font);
            cursor: pointer;
            transition: background 0.1s;
        }

        .calc-btn:active {
            background: #ddd;
        }

        .calc-btn.span-2 { grid-column: span 2; }
        .calc-btn.operator { background: #e0e0e0; color: var(--mac-blue); font-weight: bold; }
        .calc-btn.equal { background: var(--mac-blue); color: white; border-radius: 0 0 6px 6px; }
        .calc-btn:hover { filter: brightness(0.95); }

        /* Folder View */
        .folder-list {
            padding: 10px;
            height: 100%;
            overflow-y: auto;
            display: flex;
            flex-direction: column;
            gap: 5px;
        }

        .folder-item {
            display: flex;
            align-items: center;
            padding: 8px;
            border-radius: 4px;
            cursor: pointer;
            background: #f9f9f9;
            border: 1px solid #eee;
            transition: all 0.2s;
        }

        .folder-item:hover {
            background: #e5f2ff;
            border-color: var(--mac-blue);
            transform: translateX(2px);
        }

        .folder-icon {
            width: 20px;
            height: 20px;
            margin-right: 10px;
        }

        /* Text Editor */
        .text-editor {
            width: 100%;
            border: none;
            padding: 10px;
            font-family: var(--monospace-font);
            font-size: 14px;
            resize: none;
            background: #fafafa;
        }

        /* --- Dock --- */
        #dock {
            position: absolute;
            bottom: 10px;
            left: 50%;
            transform: translateX(-50%);
            width: var(--dock-width);
            height: var(--dock-height);
            background: rgba(235, 235, 235, 0.8);
            backdrop-filter: blur(20px);
            border-radius: 16px;
            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
            display: flex;
            align-items: center;
            justify-content: space-around;
            padding: 0 15px;
            z-index: 200;
            border: 1px solid rgba(255, 255, 255, 0.5);
        }

        .dock-icon {
            width: 40px;
            height: 40px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275);
            position: relative;
        }

        .dock-icon:hover {
            background: rgba(255, 255, 255, 0.5);
            transform: translateY(-5px) scale(1.1);
        }

        .dock-icon.active {
            background: rgba(255, 255, 255, 0.8);
        }

        .dock-icon img {
            width: 28px;
            height: 28px;
            image-rendering: pixelated;
        }

        .dock-label {
            font-size: 10px;
            margin-top: 2px;
            color: #333;
            opacity: 0;
            transform: translateY(10px);
            transition: all 0.2s;
            pointer-events: none;
            white-space: nowrap;
        }

        .dock-icon:hover .dock-label {
            opacity: 1;
            transform: translateY(0);
        }

        /* --- Utility --- */
        .hidden {
            display: none !important;
        }

        /* Custom Scrollbar */
        ::-webkit-scrollbar {
            width: 8px;
            height: 8px;
        }
        ::-webkit-scrollbar-track {
            background: transparent;
        }
        ::-webkit-scrollbar-thumb {
            background: #ccc;
            border-radius: 4px;
        }
        ::-webkit-scrollbar-thumb:hover {
            background: #999;
        }
    </style>
