const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
let soundOn = true;
let AC = null;
function ac(){ if(!AC) AC = new (window.AudioContext||window.webkitAudioContext)(); return AC; }
function beep(freq=880, dur=.07, type='square', vol=.06){
  if(!soundOn) return;
  try{
    const a=ac(), o=a.createOscillator(), g=a.createGain();
    o.type=type; o.frequency.value=freq; g.gain.value=vol;
    o.connect(g); g.connect(a.destination);
    o.start(); g.gain.exponentialRampToValueAtTime(.0001, a.currentTime+dur); o.stop(a.currentTime+dur);
  }catch(e){}
}
function chime(){ [523,659,784,1046].forEach((f,i)=>setTimeout(()=>beep(f,.35,'sine',.05), i*130)); }
