/* ================================================================
   WINDOW MANAGER
================================================================ */
const WM = {
  z:100, active:null, wins:{}, cascade:0,
  open(id, opts){
    if(WM.wins[id]){ const w=WM.wins[id]; if(w.classList.contains('shaded')) w.classList.remove('shaded'); WM.focus(w); return w; }
    const w = document.createElement('div');
    w.className='window'; w.dataset.id=id;
    w.style.width=(opts.w||320)+'px';
    if(opts.h) w.style.height=opts.h+'px';
    const off = 60 + (WM.cascade%8)*24;
    w.style.left=(opts.x!==undefined?opts.x:off)+'px';
    w.style.top =(opts.y!==undefined?opts.y:40+(WM.cascade%8)*22)+'px';
    WM.cascade++;
    w.innerHTML=`<div class="titlebar">
        <div class="tbox closebox" title="Close"></div>
        <div class="ttitle">${opts.title}</div>
        <div class="tbox zoombox" title="Zoom"></div>
      </div><div class="content"></div>`;
    $('#desktop').appendChild(w);
    WM.wins[id]=w;
    const content=w.querySelector('.content');
    if(typeof opts.content==='string') content.innerHTML=opts.content;
    else if(opts.content) content.appendChild(opts.content);
    if(opts.noZoom) w.querySelector('.zoombox').style.visibility='hidden';

    // focus
    w.addEventListener('pointerdown', ()=>WM.focus(w), true);
    // close
    w.querySelector('.closebox').addEventListener('click', e=>{ e.stopPropagation(); WM.close(id); });
    // zoom
    w.querySelector('.zoombox').addEventListener('click', e=>{
      e.stopPropagation();
      if(w.dataset.zoomed){
        const r=JSON.parse(w.dataset.prev); Object.assign(w.style,{left:r.l,top:r.t,width:r.w,height:r.h});
        delete w.dataset.zoomed;
      }else{
        w.dataset.prev=JSON.stringify({l:w.style.left,t:w.style.top,w:w.style.width,h:w.style.height});
        Object.assign(w.style,{left:'4px',top:'4px',width:'calc(100% - 10px)',height:'calc(100% - 10px)'});
        w.dataset.zoomed='1';
      }
      beep(660,.05);
      if(opts.onResize) opts.onResize();
    });
    // window shade (double-click titlebar)
    w.querySelector('.titlebar').addEventListener('dblclick', e=>{
      if(e.target.classList.contains('tbox')) return;
      w.classList.toggle('shaded'); beep(w.classList.contains('shaded')?500:700,.05);
    });
    // drag
    const tb=w.querySelector('.titlebar');
    tb.addEventListener('pointerdown', e=>{
      if(e.target.classList.contains('tbox')) return;
      const sx=e.clientX-w.offsetLeft, sy=e.clientY-w.offsetTop;
      tb.setPointerCapture(e.pointerId);
      const mv=ev=>{
        let nx=ev.clientX-sx, ny=ev.clientY-sy;
        nx=Math.max(-w.offsetWidth+60, Math.min(nx, innerWidth-60));
        ny=Math.max(0, Math.min(ny, innerHeight-60));
        w.style.left=nx+'px'; w.style.top=ny+'px';
      };
      const up=()=>{ tb.removeEventListener('pointermove',mv); tb.removeEventListener('pointerup',up); };
      tb.addEventListener('pointermove',mv); tb.addEventListener('pointerup',up);
    });
    WM.focus(w);
    if(opts.init) opts.init(w, content);
    return w;
  },
  focus(w){
    if(WM.active===w) return;
    if(WM.active) WM.active.classList.remove('active');
    WM.active=w; w.classList.add('active');
    w.style.zIndex=++WM.z;
    $('#frontapp').textContent = w.dataset.appname || w.querySelector('.ttitle').textContent;
  },
  close(id){
    const w=WM.wins[id]; if(!w) return;
    if(w.dataset.onclose) { try{ window[w.dataset.onclose] && window[w.dataset.onclose](); }catch(e){} }
    w.dispatchEvent(new Event('wm:close'));
    w.remove(); delete WM.wins[id];
    WM.active=null;
    const rest=Object.values(WM.wins);
    if(rest.length) WM.focus(rest[rest.length-1]);
    else $('#frontapp').textContent='Finder';
    beep(440,.04);
  }
};
document.addEventListener('keydown', e=>{
  if((e.metaKey||e.ctrlKey) && e.key.toLowerCase()==='w' && WM.active){ e.preventDefault(); WM.close(WM.active.dataset.id); }
});

